const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const windhoek = ee.Geometry.Point([17.0832, -22.5609]); // Windhoek, Namibia
  const region = windhoek.buffer(50000); // 50km buffer around Windhoek

  // 2. Data Acquisition - Sentinel-2 for NDVI
  function getFebCollection(year) {
    const startDate = ee.Date.fromYMD(year, 1, 1); // February 1st
    const endDate = ee.Date.fromYMD(year, 2, 1); // March 1st (exclusive)

    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  }

  // Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // NDVI calculation
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Process a single year's February NDVI
  function processYearNDVI(year) {
    let collection = getFebCollection(year)
      .map(maskClouds)
      .map(addNDVI);

    const count = collection.size();
    if (count.getInfo() === 0) return null;

    // Create mosaic and calculate mean NDVI
    const mosaic = collection.select('NDVI').median();
    const stats = mosaic.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    });

    const meanNDVI = stats.get('NDVI');
    const pixelCount = mosaic.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI');

    return {
      meanNDVI: meanNDVI,
      pixelCount: pixelCount,
      imageCount: count
    };
  }

  // Process 2021 data
  const target2021 = processYearNDVI(2021);
  if (!target2021) {
    print("No 2021 February images found.");
    print("<answer>C1</answer>");
    return;
  }

  // Process baseline years (2010-2020)
  const baselineYears = [];
  for (let year = 2010; year <= 2020; year++) {
    const result = processYearNDVI(year);
    if (result) {
      baselineYears.push(result);
    }
  }

  if (baselineYears.length === 0) {
    print("No baseline years (2010-2020) found.");
    print("<answer>C1</answer>");
    return;
  }

  // Calculate baseline average
  const baselineMeans = ee.List(baselineYears.map(y => y.meanNDVI));
  const baselineAvg = ee.List(baselineMeans).reduce(ee.Reducer.mean());

  // Get values
  const targetNDVI = target2021.meanNDVI.getInfo();
  const baselineNDVI = baselineAvg.getInfo();
  const targetPixels = target2021.pixelCount.getInfo();

  print(`2021 Feb: ${targetNDVI ? targetNDVI.toFixed(3) : 'No data'}`);
  print(`Baseline Avg: ${baselineNDVI ? baselineNDVI.toFixed(3) : 'No data'}`);
  print(`2021 Valid Pixels: ${targetPixels}`);
  print(`Baseline Years: ${baselineYears.length}/11`);

  // Validation checks
  if (targetPixels === 0) {
    print("<answer>C2</answer>");
    return;
  }

  if (targetNDVI === null || baselineNDVI === null || 
      isNaN(targetNDVI) || isNaN(baselineNDVI) ||
      targetNDVI < -1 || targetNDVI > 1 || 
      baselineNDVI < -1 || baselineNDVI > 1) {
    print("<answer>C3</answer>");
    return;
  }

  // Final comparison
  if (targetNDVI > baselineNDVI) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
